### Step 4: Lifecycle module — signal detection and proposal generation

Create `src/conventions/lifecycle.rs`. This is the core logic module. It reads convention history from the DB and generates proposals when signals are detected.

```rust
// src/conventions/lifecycle.rs

const TREND_WINDOW: usize = 3; // consecutive snapshots needed

pub enum Signal {
    PromoteToPreferred {
        convention_id: String,
        rationale: String,
    },
    Deprecate {
        convention_id: String,
        rationale: String,
    },
    ProposeDelete {
        convention_id: String,
        rationale: String,
    },
}

/// Analyze all conventions and generate proposals for detected signals.
/// Called after FCA rebuild + history recording.
pub fn detect_signals(db: &Db) -> Result<Vec<Signal>> {
    let conventions = db.all_conventions_merged()?;
    let mut signals = Vec::new();

    for conv in &conventions {
        let history = db.convention_history(&conv.id, TREND_WINDOW * 2)?;
        if history.len() < TREND_WINDOW {
            continue;
        }

        // Get unique snapshots (most recent first, already ordered by recorded_at DESC)
        let recent: Vec<&ConventionHistoryRow> = dedup_by_snapshot(&history, TREND_WINDOW);

        let lifecycle = conv.lifecycle_state.as_deref().unwrap_or("descriptive");

        match lifecycle {
            "descriptive" => {
                // Stable high support for TREND_WINDOW snapshots → promote
                if recent.iter().all(|h| h.support >= 3 && h.confidence >= 0.9) {
                    signals.push(Signal::PromoteToPreferred {
                        convention_id: conv.id.clone(),
                        rationale: format!(
                            "stable high support ({}) and confidence ({:.0}%) over {} snapshots",
                            recent[0].support,
                            recent[0].confidence * 100.0,
                            TREND_WINDOW,
                        ),
                    });
                }
            }
            "preferred" => {
                // Declining support over TREND_WINDOW snapshots → deprecate
                if is_declining_support(&recent) {
                    signals.push(Signal::Deprecate {
                        convention_id: conv.id.clone(),
                        rationale: format!(
                            "support declining: {} → {} over {} snapshots",
                            recent.last().unwrap().support,
                            recent[0].support,
                            TREND_WINDOW,
                        ),
                    });
                }
            }
            "deprecated" => {
                // Zero support for TREND_WINDOW snapshots → propose deletion
                if recent.iter().all(|h| h.support == 0) {
                    signals.push(Signal::ProposeDelete {
                        convention_id: conv.id.clone(),
                        rationale: format!(
                            "zero matching symbols for {} consecutive snapshots",
                            TREND_WINDOW,
                        ),
                    });
                }
            }
            _ => {}
        }
    }

    Ok(signals)
}

fn dedup_by_snapshot<'a>(
    history: &'a [ConventionHistoryRow],
    limit: usize,
) -> Vec<&'a ConventionHistoryRow>
// Take one entry per unique snapshot_id, most recent first, up to limit

fn is_declining_support(snapshots: &[&ConventionHistoryRow]) -> bool
// True if each successive snapshot has strictly less support than the previous
// (oldest to newest: support is going down)

/// Generate proposals from signals, respecting dismissal guards.
pub fn generate_proposals(db: &Db, signals: Vec<Signal>) -> Result<Vec<i64>> {
    let mut created = Vec::new();
    for signal in signals {
        let (conv_id, transition, rationale, direction) = match &signal {
            Signal::PromoteToPreferred { convention_id, rationale } =>
                (convention_id, "descriptive→preferred", rationale, "promote"),
            Signal::Deprecate { convention_id, rationale } =>
                (convention_id, "preferred→deprecated", rationale, "demote"),
            Signal::ProposeDelete { convention_id, rationale } =>
                (convention_id, "deprecated→deleted", rationale, "demote"),
        };

        // Skip if already has a pending proposal
        if db.has_pending_proposal(conv_id)? {
            continue;
        }

        // Skip if dismissed with same signal direction (no reversal)
        if db.dismissed_proposal_for_convention(conv_id, direction)?.is_some() {
            continue;
        }

        let id = db.create_proposal(conv_id, transition, rationale, direction)?;
        created.push(id);
    }
    Ok(created)
}
```

### Step 5: Inverse check — ConventionMatch + check_inverse on FcaEngine

The existing `check` finds violations (antecedent matched, consequent NOT satisfied). The inverse check finds *matches* — code that follows a deprecated/forbidden pattern (both antecedent AND consequent satisfied). This warns "you're writing code that follows an anti-pattern."

Add to `src/conventions/engine.rs`:

```rust
#[derive(Debug, Clone, PartialEq)]
pub struct ConventionMatch {
    pub symbol: String,
    pub file: String,
    pub convention_id: String,
    pub antecedent: Vec<String>,
    pub consequent: Vec<String>,
    pub lifecycle_state: String,  // "deprecated" or "forbidden"
    pub support: usize,
    pub confidence: f64,
}

impl FcaEngine {
    /// Inverse of `check`: finds symbols that MATCH a convention's full pattern.
    /// Used for deprecated/forbidden conventions — matching the pattern is the problem.
    pub fn check_inverse(
        &self,
        changed_symbols: &[SymbolAttrs],
        deprecated_ids: &HashSet<String>,
        forbidden_ids: &HashSet<String>,
    ) -> Vec<ConventionMatch> {
        let mut matches = Vec::new();
        for conv in &self.conventions {
            let lifecycle = if deprecated_ids.contains(&conv.id) {
                "deprecated"
            } else if forbidden_ids.contains(&conv.id) {
                "forbidden"
            } else {
                continue;
            };

            for sym in changed_symbols {
                // Component scope check
                if let Some(conv_comp) = &conv.component_id {
                    if sym.component_id.as_ref() != Some(conv_comp) {
                        continue;
                    }
                }

                let attrs: HashSet<&str> = sym.attributes.iter().map(|a| a.as_str()).collect();
                let has_antecedent = conv.antecedent.iter().all(|a| attrs.contains(a.as_str()));
                let has_consequent = conv.consequent.iter().all(|c| attrs.contains(c.as_str()));

                if has_antecedent && has_consequent {
                    matches.push(ConventionMatch {
                        symbol: sym.name.clone(),
                        file: sym.file.clone(),
                        convention_id: conv.id.clone(),
                        antecedent: conv.antecedent.clone(),
                        consequent: conv.consequent.clone(),
                        lifecycle_state: lifecycle.to_string(),
                        support: conv.support,
                        confidence: conv.confidence,
                    });
                }
            }
        }
        matches
    }
}
```

