### Step 7: MCP tool — sutra_conventions

Create `src/tools/conventions.rs`:

```rust
#[derive(Debug, Deserialize, JsonSchema)]
pub struct ConventionsArgs {
    pub workspace: String,
    /// Action: "list", "accept", "dismiss", "set_lifecycle"
    pub action: String,
    /// Proposal ID (for accept/dismiss)
    #[serde(default)]
    pub proposal_id: Option<i64>,
    /// Convention ID (for set_lifecycle)
    #[serde(default)]
    pub convention_id: Option<String>,
    /// Lifecycle state (for set_lifecycle): descriptive, preferred, deprecated, forbidden
    #[serde(default)]
    pub lifecycle_state: Option<String>,
    /// Reason for lifecycle change
    #[serde(default)]
    pub reason: Option<String>,
}

pub fn handle(db: &Db, args: &ConventionsArgs) -> Result<serde_json::Value> {
    match args.action.as_str() {
        "list" => {
            let conventions = db.all_conventions_merged()?;
            let proposals = db.pending_proposals()?;
            // Format: each convention with its state, plus pending proposals section
        }
        "accept" => {
            let id = args.proposal_id.ok_or(...)?;
            // 1. Get the proposal
            // 2. Apply the transition via db.set_convention_lifecycle
            // 3. Resolve the proposal as accepted
        }
        "dismiss" => {
            let id = args.proposal_id.ok_or(...)?;
            db.resolve_proposal(id, "dismissed")?;
        }
        "set_lifecycle" => {
            let conv_id = args.convention_id.as_ref().ok_or(...)?;
            let state = args.lifecycle_state.as_ref().ok_or(...)?;
            // Validate state is one of: descriptive, preferred, deprecated, forbidden
            db.set_convention_lifecycle(conv_id, state, args.reason.as_deref())?;
        }
        _ => return Err(...)
    }
}
```

Register in `src/mcp.rs`:

```rust
#[tool(description = "Manage convention lifecycle: list conventions with state and pending proposals, \
    accept or dismiss proposals, or manually set lifecycle state. \
    Actions: list, accept (proposal_id), dismiss (proposal_id), \
    set_lifecycle (convention_id, lifecycle_state, reason).")]
pub async fn sutra_conventions(
    &self,
    Parameters(args): Parameters<ConventionsArgs>,
) -> Result<String, ErrorData> {
    let _ws = self.resolve_workspace(&args.workspace)?;
    let db = self.get_db(&args.workspace)?;
    let result = tools::conventions::handle(&db, &args).map_err(sutra_to_rmcp)?;
    self.wrap_response(&db, result)
}
```

